import 'dart:typed_data';

/// PLZPART's shipped tables (assets/tables/plasma.srt, built by
/// tool/convert_plasma.py from the original TASM includes).
///
///   psini / lsini4 / lsini16 — the plasma's three sine tables (PSINI.INC,
///     LSINI4.INC, LSINI16.INC; generated by PLZ.C's `#ifdef DO_TABLES` block,
///     and verified byte-exact against it by the converter).
///   ptau — the 129-entry cosine ramp init_plz() builds all five palettes from.
///   sinit — a 15-bit sine over 1024 units (SINIT.INC). INCLUDE.ASM sets
///     `kosinit = sinit + 512` bytes, i.e. the SAME table read 256 entries in;
///     that is why it carries 1280 entries and not 1024.
///   spline — SPLINE.INC: four 256-entry basis rows (1.0 = 32768) for the cubic
///     the camera/object path is evaluated through.
///   rata — RATA.INC: the path's control points, 8 channels each
///     (tx, ty, dis, kx, ky, kz, ls_kx, ls_ky).
class PlasmaTables {
  final Uint8List psini; // 16384
  final Int16List lsini4; // 8192
  final Int16List lsini16; // 8192
  final Uint8List ptau; // 129
  final Int16List sinit; // 1280
  final Int16List spline; // 1024
  final Int16List rata; // points * 8
  final int points;

  PlasmaTables._(this.psini, this.lsini4, this.lsini16, this.ptau, this.sinit,
      this.spline, this.rata, this.points);

  /// kosinit[a] — the cosine, which is literally sinit a quarter turn along.
  int kosinit(int a) => sinit[a + 256];

  static PlasmaTables decode(Uint8List bytes) {
    if (bytes[0] != 0x53 ||
        bytes[1] != 0x52 ||
        bytes[2] != 0x50 ||
        bytes[3] != 0x32) {
      throw const FormatException('not an SRP2 plasma table');
    }
    final d = ByteData.sublistView(bytes);
    var o = 5;
    final psini = Uint8List.fromList(bytes.sublist(o, o + 16384));
    o += 16384;
    final lsini4 = Int16List(8192);
    for (var i = 0; i < 8192; i++) {
      lsini4[i] = d.getInt16(o + i * 2, Endian.little);
    }
    o += 16384;
    final lsini16 = Int16List(8192);
    for (var i = 0; i < 8192; i++) {
      lsini16[i] = d.getInt16(o + i * 2, Endian.little);
    }
    o += 16384;
    final ptau = Uint8List.fromList(bytes.sublist(o, o + 129));
    o += 129;
    final sinit = Int16List(1280);
    for (var i = 0; i < 1280; i++) {
      sinit[i] = d.getInt16(o + i * 2, Endian.little);
    }
    o += 2560;
    final spline = Int16List(1024);
    for (var i = 0; i < 1024; i++) {
      spline[i] = d.getInt16(o + i * 2, Endian.little);
    }
    o += 2048;
    final points = d.getUint16(o, Endian.little);
    o += 2;
    final rata = Int16List(points * 8);
    for (var i = 0; i < points * 8; i++) {
      rata[i] = d.getInt16(o + i * 2, Endian.little);
    }
    return PlasmaTables._(
        psini, lsini4, lsini16, ptau, sinit, spline, rata, points);
  }
}
